@torch.jit.script
def _normalized_gru_sequence(
    projected: torch.Tensor,
    hidden: torch.Tensor,
    recurrent_weight: torch.Tensor,
    recurrent_bias: torch.Tensor,
    reset_weight: torch.Tensor,
    reset_bias: torch.Tensor,
    update_weight: torch.Tensor,
    update_bias: torch.Tensor,
    candidate_weight: torch.Tensor,
    candidate_bias: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor]:
    outputs = torch.jit.annotate(list[torch.Tensor], [])
    width = hidden.size(1)
    for timestep in range(projected.size(1)):
        input_reset, input_update, input_candidate = projected[:, timestep].chunk(3, dim=-1)
        hidden_reset, hidden_update, hidden_candidate = torch.nn.functional.linear(
            hidden, recurrent_weight, recurrent_bias
        ).chunk(3, dim=-1)
        reset = torch.sigmoid(torch.nn.functional.layer_norm(
            input_reset + hidden_reset, [width], reset_weight, reset_bias, 1e-5
        ))
        update = torch.sigmoid(torch.nn.functional.layer_norm(
            input_update + hidden_update, [width], update_weight, update_bias, 1e-5
        ))
        candidate = torch.tanh(torch.nn.functional.layer_norm(
            input_candidate + reset * hidden_candidate,
            [width], candidate_weight, candidate_bias, 1e-5
        ))
        hidden = (1.0 - update) * candidate + update * hidden
        outputs.append(hidden)
    return torch.stack(outputs, dim=1), hidden


class LayerNormGRU(nn.GRU):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.gate_norms = nn.ModuleList([
            nn.ModuleList([nn.LayerNorm(self.hidden_size) for _ in range(3)])
            for _ in range(self.num_layers)
        ])

    def forward(self, input: torch.Tensor, hx: torch.Tensor | None = None):
        layer_input = input if self.batch_first else input.transpose(0, 1)
        if hx is None:
            hx = layer_input.new_zeros(
                self.num_layers, layer_input.size(0), self.hidden_size
            )
        final_states = []
        for layer, norms in enumerate(self.gate_norms):
            projected = torch.nn.functional.linear(
                layer_input,
                getattr(self, f'weight_ih_l{layer}'),
                getattr(self, f'bias_ih_l{layer}'),
            )
            layer_input, final_hidden = _normalized_gru_sequence(
                projected, hx[layer],
                getattr(self, f'weight_hh_l{layer}'),
                getattr(self, f'bias_hh_l{layer}'),
                norms[0].weight, norms[0].bias,
                norms[1].weight, norms[1].bias,
                norms[2].weight, norms[2].bias,
            )
            final_states.append(final_hidden)
            if layer + 1 < self.num_layers and self.dropout > 0.0:
                layer_input = torch.nn.functional.dropout(
                    layer_input, p=self.dropout, training=self.training
                )
